import { siteConfig } from '../data/siteConfig.js';
import { sectionLabel, arrow, placeholder } from './shared.js';
export function Contact() { return `<section id="contact" class="contact section" aria-labelledby="contact-title"><div class="contact-earth" aria-hidden="true"></div><div class="container">${sectionLabel('06','CONTACT')}<div class="contact-content"><span class="eyebrow reveal">THE NEXT HORIZON STARTS WITH A CONVERSATION.</span><h2 id="contact-title" class="reveal">Let’s build something<br><span class="soft-text">meaningful.</span></h2><p class="reveal">Have an idea? Let’s make it real.</p><div class="contact-links reveal" aria-label="Contact links — placeholders, not yet available">${siteConfig.contact.map(c=>`<span class="contact-placeholder" aria-disabled="true">${c}${arrow}</span>`).join('')}</div><div class="reveal">${placeholder('CONTACT LINKS · COMING LATER')}</div><p class="small-note reveal">联系方式待提供。</p></div></div></section>`; }
